/**
 * Types the hooks from an OpenAPI description of the API, as generated by
 * openapi-typescript (its `paths` type). Types only: at runtime these are the
 * plain hooks.
 *
 *   import type { paths } from "./schema";
 *   export const { useQuery, useMutation, useSuspenseQuery } =
 *     createTypedHooks<paths, "/api/">();
 *
 *   // data: the response of GET /api/users/{id}/
 *   const { data } = useQuery(`users/${id}/`);
 *
 * The prefix is the part of the schema's paths that the cache's `baseUrl`
 * already holds. A path is matched to the schema's templates segment by
 * segment: `users/${string}/` is `/api/users/{id}/`, never
 * `/api/users/{id}/posts/`, and a fixed segment (`users/me/`) wins over a
 * parameter (`users/{id}/`). A path matching no route is a type error.
 */
import { useMutation } from "./hooks/useMutation";
import type { MutateOptions, UseMutationOptions } from "./hooks/useMutation";
import { useQuery } from "./hooks/useQuery";
import type { UseQueryOptions, UseQueryResult } from "./hooks/useQuery";
import { useSuspenseQuery } from "./hooks/useSuspenseQuery";
import type {
  SuspenseQueryOptions,
  UseSuspenseQueryResult,
} from "./hooks/useSuspenseQuery";
import type { HttpMethod } from "./restCache";

type Method = Lowercase<HttpMethod>;

type Split<S extends string> = S extends `${infer Head}/${infer Tail}`
  ? [Head, ...Split<Tail>]
  : [S];

// A template's `{param}` segment matches any segment, the others themselves.
type SegmentMatches<Template extends string, Segment extends string> =
  Template extends `{${string}}` ? true : Segment extends Template ? true : false;

type SegmentsMatch<Template extends string[], Path extends string[]> =
  Template extends [
    infer TemplateHead extends string,
    ...infer TemplateTail extends string[],
  ]
    ? Path extends [infer PathHead extends string, ...infer PathTail extends string[]]
      ? SegmentMatches<TemplateHead, PathHead> extends true
        ? SegmentsMatch<TemplateTail, PathTail>
        : false
      : false
    : Path extends []
      ? true
      : false;

/** The schema's paths having method `M`, without the prefix. */
type Templates<Paths, Prefix extends string, M extends Method> = {
  [K in keyof Paths & string]: K extends `${Prefix}${infer Template}`
    ? Paths[K] extends Record<M, object>
      ? Template
      : never
    : never;
}[keyof Paths & string];

type IsParam<Segment extends string> = Segment extends `{${string}}` ? true : false;

// A is more specific than B: segment by segment, a fixed segment of A where
// B has a parameter, and never the reverse.
type MoreSpecific<
  A extends string[],
  B extends string[],
  Strictly extends boolean = false,
> = A extends [infer AHead extends string, ...infer ATail extends string[]]
  ? B extends [infer BHead extends string, ...infer BTail extends string[]]
    ? IsParam<AHead> extends true
      ? IsParam<BHead> extends true
        ? MoreSpecific<ATail, BTail, Strictly>
        : false
      : MoreSpecific<ATail, BTail, IsParam<BHead> extends true ? true : Strictly>
    : false
  : Strictly;

type Matching<Paths, Prefix extends string, M extends Method, P extends string> = {
  [T in Templates<Paths, Prefix, M>]: SegmentsMatch<Split<T>, Split<P>> extends true
    ? T
    : never;
}[Templates<Paths, Prefix, M>];

// The matching templates no other matching one is more specific than:
// `users/me/` over `users/{id}/` for `users/me/`.
type MostSpecific<All extends string, T extends string = All> = T extends unknown
  ? true extends (
      All extends unknown ? MoreSpecific<Split<All>, Split<T>> : never
    )
    ? never
    : T
  : never;

/** The template a concrete path is an instance of, for method `M`. */
export type RouteOf<
  Paths,
  Prefix extends string,
  M extends Method,
  P extends string,
> = P extends unknown ? MostSpecific<Matching<Paths, Prefix, M, P>> : never;

type OperationOf<
  Paths,
  Prefix extends string,
  M extends Method,
  P extends string,
> = `${Prefix}${RouteOf<Paths, Prefix, M, P>}` extends infer K
  ? K extends keyof Paths
    ? Paths[K] extends Record<M, infer Operation>
      ? Operation
      : never
    : never
  : never;

type SuccessStatus = 200 | 201 | 202 | 203 | 204;

/** The JSON body of an operation's successful responses (void if none). */
export type ResponseOf<Operation> = Operation extends { responses: infer Responses }
  ? {
      [S in keyof Responses & SuccessStatus]: Responses[S] extends {
        content: { "application/json": infer Body };
      }
        ? Body
        : void;
    }[keyof Responses & SuccessStatus]
  : never;

/**
 * The request body of an operation: its JSON body, or FormData when it also
 * accepts multipart (never if it takes no body).
 */
export type BodyOf<Operation> = Operation extends {
  requestBody?: { content: infer Content };
}
  ?
      | (Content extends { "application/json": infer Body } ? Body : never)
      | (Content extends { "multipart/form-data": unknown } ? FormData : never)
  : never;

type QueryParamsOf<Operation> = Operation extends {
  parameters: { query?: infer Query };
}
  ? [Query] extends [never | undefined]
    ? never
    : { [K in keyof NonNullable<Query>]?: string }
  : never;

/** Leaves `P` as is when it matches a route, else makes the call an error. */
type CheckedPath<
  Paths,
  Prefix extends string,
  M extends Method,
  P extends string,
> = [RouteOf<Paths, Prefix, M, P>] extends [never]
  ? `No ${Uppercase<M>} route in the API schema matches "${P}"`
  : P;

type TypedQueryOptions<Operation> = Omit<UseQueryOptions, "params" | "method" | "body"> & {
  params?: QueryParamsOf<Operation>;
};

type TypedMutate<Paths, Prefix extends string, M extends Method, P extends string> = <
  SubPath extends string = "",
>(
  mutationOptions?: Omit<MutateOptions, "body" | "subPath"> & {
    subPath?: SubPath;
    body?: BodyOf<OperationOf<Paths, Prefix, M, `${P}${SubPath}`>>;
  }
) => Promise<ResponseOf<OperationOf<Paths, Prefix, M, `${P}${SubPath}`>> | void>;

type TypedUseMutationResult<
  Paths,
  Prefix extends string,
  M extends Method,
  P extends string,
> = readonly [
  TypedMutate<Paths, Prefix, M, P>,
  {
    data: ResponseOf<OperationOf<Paths, Prefix, M, P>> | undefined;
    error: Error | undefined;
    loading: boolean;
  },
];

export interface TypedHooks<Paths, Prefix extends string> {
  useQuery: <P extends string>(
    path: CheckedPath<Paths, Prefix, "get", P>,
    options?: TypedQueryOptions<OperationOf<Paths, Prefix, "get", P>>
  ) => UseQueryResult<ResponseOf<OperationOf<Paths, Prefix, "get", P>>>;
  useSuspenseQuery: <P extends string>(
    path: CheckedPath<Paths, Prefix, "get", P>,
    options?: Omit<SuspenseQueryOptions, "params" | "method" | "body"> & {
      params?: QueryParamsOf<OperationOf<Paths, Prefix, "get", P>>;
    }
  ) => UseSuspenseQueryResult<ResponseOf<OperationOf<Paths, Prefix, "get", P>>>;
  /**
   * The route is the hook's path plus the `subPath` given to `mutate`, if
   * any: `useMutation("users/", { method: "PATCH" })` then
   * `mutate({ subPath: `${id}/`, body })` is PATCH /users/{id}/.
   */
  useMutation: <P extends string, M extends HttpMethod>(
    path: P,
    options: Omit<UseMutationOptions, "method"> & { method: M }
  ) => TypedUseMutationResult<Paths, Prefix, Lowercase<M>, P>;
}

export const createTypedHooks = <Paths, Prefix extends string = "">() =>
  ({ useQuery, useSuspenseQuery, useMutation }) as unknown as TypedHooks<
    Paths,
    Prefix
  >;
